const tabId = 343605502;
const details = await browserjs(tabId, () => {
  const commitRows = Array.from(document.querySelectorAll('[data-testid="commit-row-item"], li[class*="CommitRow"], .Box-row'));
  const pagination = Array.from(document.querySelectorAll('a[rel="nofollow"], .pagination a, [data-testid="pagination"] a, a[class*="Button"]')).map(a => ({
    text: a.textContent.trim(),
    href: a.href
  }));

  // Extract structured commit info
  const items = [];
  const groups = document.querySelectorAll('li[data-testid="commit-row-item"], [data-testid="commit-row-item"]');
  for (const el of commitRows) {
    const titleEl = el.querySelector('a[href*="/commit/"], [data-testid="commit-title-item"]');
    const shaEl = el.querySelector('a[href*="/commit/"][class*="Link--secondary"], code, [data-testid="commit-sha"]');
    const timeEl = el.querySelector('relative-time, time');
    const authorEl = el.querySelector('[data-hovercard-type="user"], a[class*="commit-author"]');
    items.push({
      text: el.innerText.replace(/\s+/g, ' ').trim(),
      title: titleEl?.textContent.trim(),
      href: titleEl?.href,
      sha: shaEl?.textContent.trim(),
      date: timeEl ? (timeEl.getAttribute('datetime') || timeEl.textContent) : null,
      author: authorEl?.textContent.trim()
    });
  }

  return {
    items,
    pagination,
    hasOlder: document.body.innerText.includes("Older"),
    hasNewer: document.body.innerText.includes("Newer")
  };
});

